209:     camera.lookAt(centerX, 0, centerZ);
210:     camera.rotation.z = 0;
211:     camera.left = -50 * aspect / currentZoom; camera.right = 50 * aspect / currentZoom;
212:     camera.top = 50 / currentZoom; camera.bottom = -50 / currentZoom; camera.updateProjectionMatrix();
213: 
214:     const live = new Set();
215:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
216:       live.add(entity.id);
217:       let obj = entities.get(entity.id);
218:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
219:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
