230:       obj.userData.model.rotation.y = entity.target ? Math.atan2(entity.target.x - entity.x, entity.target.y - entity.y) - obj.rotation.y : 0;
231:       obj.userData.health.visible = entity.hp < entity.max;
232:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
233:       obj.userData.healthFill.scale.x = ratio;
