285:   function syncEffects(frame) {
286:     const key = `${frame.shots.length}:${frame.particles.length}:${Math.floor(frame.time * 10)}`;
287:     if (transientKey === key) return;
288:     transientKey = key;
289:     while (transientRoot.children.length) {
