const fs = require('fs');
const vm = require('vm');
const source = fs.readFileSync('game.js', 'utf8')
  .replace(/^import .*\n/, '')
  .replace(/\}\)\(\);\s*$/, `window.__test={update,setup,beginBuild,handleMap,get state(){return {units,buildings,enemies,nodes,credits,time,playing,over,enemyClock,production,faction};}};})();`);
class Element {
  constructor(id='') { this.id=id; this.textContent=''; this.innerHTML=''; this.disabled=false; this.dataset={}; this.style={}; this.handlers={}; this.children=[]; this.classList={add(){},remove(){},toggle(){},contains(){return false;}}; this.tagName=id.includes('btn')?'BUTTON':'DIV'; }
  addEventListener(name, fn) { this.handlers[name]=fn; }
  click() { this.onclick?.({currentTarget:this}); }
  getBoundingClientRect(){return {left:0,top:0,width:1000,height:700};}
  querySelectorAll(selector){ if(selector==='.build-card') return [...this.innerHTML.matchAll(/data-build="([^"]+)"/g)].map(m=>{const e=new Element();e.dataset.build=m[1];return e;}); return []; }
}
const ids=['battlefield','credits','income','power','army-count','selection-type','selection-name','selection-icon','selection-health','toast','start-screen','pause-screen','end-screen','objective-card','build-list','build-category','clock','start-btn','faction-label','faction-doctrine','deploy-faction','pause-btn','resume-btn','restart-btn','sound-btn','end-kicker','end-title','end-copy','again-btn'];
const elements=Object.fromEntries(ids.map(id=>[id,new Element(id)]));
elements.battlefield.getContext=()=>({});
const actions=['select','move','attack','harvest'].map(action=>{const e=new Element();e.dataset.action=action;return e;});
const factions=['usa','china','russia'].map(faction=>{const e=new Element();e.dataset.faction=faction;return e;});
const tabs=['structures','units','defenses'].map(tab=>{const e=new Element();e.dataset.tab=tab;return e;});
const document={getElementById:id=>elements[id]||(elements[id]=new Element(id)),querySelectorAll:s=>s==='.action-card'?actions:s==='.faction-option'?factions:s==='.build-tab'?tabs:s==='.build-card'?elements['build-list'].querySelectorAll(s):[],querySelector:s=>actions.find(e=>e.dataset.action===s.match(/data-action="([^"]+)/)?.[1]),activeElement:{tagName:'BODY'}};
const window={addEventListener(){},devicePixelRatio:1};
const context={document,window,performance:{now:()=>0},requestAnimationFrame(){},console,Math};
context.createBattlefield=()=>({resize(){},render(){}});
vm.runInNewContext(source,context,{filename:'game.js'});
const game=window.__test;
module.exports={game,elements,actions,factions,tabs};

